create table public.user_accounts(user_id uuid primary key references auth.users(id) on delete cascade,persona text not null default 'learner' check(persona in ('learner','institute','employer','government','admin')),display_name text,preferred_language text not null default 'en' check(preferred_language in ('en','hi')),status text not null default 'active' check(status in ('active','suspended','deletion_requested')),terms_version text,terms_accepted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.user_accounts enable row level security;create policy "users read own account" on public.user_accounts for select using(user_id=auth.uid());create policy "users update own account" on public.user_accounts for update using(user_id=auth.uid()) with check(user_id=auth.uid());
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.user_accounts(user_id,persona,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'persona','learner'),new.raw_user_meta_data->>'display_name');return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create table public.organization_invitations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,email text not null,role text not null,token_hash text not null unique,status text not null default 'pending' check(status in ('pending','accepted','revoked','expired')),invited_by uuid not null references auth.users(id),expires_at timestamptz not null default(now()+interval '7 days'),accepted_by uuid references auth.users(id),created_at timestamptz not null default now());alter table public.organization_invitations enable row level security;create policy "invitees read invitation" on public.organization_invitations for select using(lower(email)=lower(coalesce(auth.jwt()->>'email','')));create index org_invitation_email_idx on public.organization_invitations(lower(email),status);
create trigger user_accounts_updated before update on public.user_accounts for each row execute function public.set_updated_at();
